// Builds public/puzzles/<difficulty>.json from the Sudoku Exchange puzzle bank
// (https://github.com/grantm/sudoku-exchange-puzzle-bank, public domain).
// The bank's puzzles were generated by QQWing and rated with Sukaku Explainer;
// this script re-checks every puzzle it imports and computes its solution.
//
// Usage: node --experimental-strip-types scripts/import-puzzles.ts <bank-dir> [count]

import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { solvableWithSingles, solve } from '../src/game/solver.ts'

const BANK_FILES = { easy: 'easy.txt', medium: 'medium.txt', hard: 'hard.txt', extreme: 'diabolical.txt' }
const LINE = /^([0-9a-f]{12}) ([0-9]{81}) +([0-9]+\.[0-9])$/

const [bankDir, countArg = '1000'] = process.argv.slice(2)
if (!bankDir) {
  console.error('Usage: node --experimental-strip-types scripts/import-puzzles.ts <bank-dir> [count]')
  process.exit(1)
}
const count = Number(countArg)

for (const [difficulty, file] of Object.entries(BANK_FILES)) {
  const lines = readFileSync(join(bankDir, file), 'utf8').split('\n').filter(Boolean)
  const puzzles: { id: string; givens: string; solution: string; rating: number }[] = []
  let rejected = 0
  let singles = 0

  // Lines are ordered by a hash of the puzzle, so the first N are a random sample.
  for (const line of lines) {
    if (puzzles.length === count) break
    const match = LINE.exec(line)
    if (!match) throw new Error(`Unexpected line in ${file}: ${line}`)
    const [, id, digits, rating] = match
    const givens = [...digits].map(Number)
    const { count: solutions, solution } = solve(givens)
    if (solutions !== 1 || !solution) {
      rejected++
      continue
    }
    if (solvableWithSingles(givens)) singles++
    puzzles.push({ id, givens: digits, solution: solution.join(''), rating: Number(rating) })
  }

  const ratings = puzzles.map((p) => p.rating)
  const avgGivens = puzzles.reduce((n, p) => n + [...p.givens].filter((d) => d !== '0').length, 0) / puzzles.length
  console.log(
    `${difficulty.padEnd(8)} ${puzzles.length} puzzles, ${rejected} rejected (not exactly one solution), ` +
      `SE rating ${Math.min(...ratings)}–${Math.max(...ratings)}, avg ${avgGivens.toFixed(1)} givens, ` +
      `${singles} solvable with singles only`,
  )
  writeFileSync(join('public/puzzles', `${difficulty}.json`), JSON.stringify(puzzles))
}
